CREATE OR REPLACE FUNCTION astra_ingestion_v1.independent_verify_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
 SET lock_timeout TO '2s'
AS $function$
DECLARE
 v_p astra_ingestion_v1.partitions%ROWTYPE;
 v_j astra_ingestion_v1.jobs%ROWTYPE;
 v_receipt astra_ingestion_v1.receipts%ROWTYPE;
 v_row astra_ingestion_v1.records%ROWTYPE;
 v_parsed jsonb;
 v_payload jsonb;
 v_expected jsonb:='{}'::jsonb;
 v_actual jsonb:='{}'::jsonb;
 v_expected_hash text;
 v_actual_hash text;
 v_expected_count integer:=0;
 v_actual_count integer:=0;
 v_pages integer:=0;
 v_token text:=NULL;
 v_seen_tokens text[]:='{}'::text[];
 v_key text;
 v_state text:='passed';
 v_failure text:=NULL;
 v_receipt_bytes bigint:=0;
 v_scope_hash text;
BEGIN
 IF NOT pg_catalog.pg_try_advisory_xact_lock(706314020261030) THEN
    RETURN pg_catalog.jsonb_build_object('state','already_running'); END IF;
 SELECT p.* INTO v_p
   FROM astra_ingestion_v1.partitions p
   JOIN astra_ingestion_v1.jobs j ON j.id=p.job_id
   WHERE p.status='verified' AND j.status='completed'
     AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.independent_verifications v
        WHERE v.partition_id=p.id AND v.verifier_version='sql_v1')
   ORDER BY j.created_at,p.symbol,p.start_at LIMIT 1;
 IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object('state','idle'); END IF;
 SELECT * INTO STRICT v_j FROM astra_ingestion_v1.jobs WHERE id=v_p.job_id;

 BEGIN
   v_scope_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
     astra_ingestion_v1.rpc_canonical(v_j.spec::jsonb),'UTF8')),'hex');
   IF v_scope_hash IS DISTINCT FROM v_j.scope_hash THEN
      RAISE EXCEPTION 'Immutable job scope hash is inconsistent'; END IF;
   -- All raw bytes remain private. Only hashes and counts reach the attestation.
   SELECT COALESCE(SUM(pg_catalog.octet_length(raw_body)),0) INTO v_receipt_bytes
     FROM astra_ingestion_v1.receipts WHERE partition_id=v_p.id;
   IF v_receipt_bytes>8388608 THEN
      RAISE EXCEPTION 'Verifier bounded source payload is exceeded'; END IF;
   FOR v_receipt IN SELECT * FROM astra_ingestion_v1.receipts
     WHERE partition_id=v_p.id ORDER BY page_no
   LOOP
     IF v_receipt.page_no<>v_pages OR v_receipt.token_in IS DISTINCT FROM v_token
        OR (v_pages>0 AND v_token IS NULL) THEN
        RAISE EXCEPTION 'Retained source pagination chain is incomplete'; END IF;
     IF pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        v_receipt.raw_body,'UTF8')),'hex')<>v_receipt.body_sha256 THEN
        RAISE EXCEPTION 'Retained receipt SHA-256 mismatch'; END IF;
     v_parsed:=astra_ingestion_v1.rpc_parse_source(
       v_receipt.raw_body,v_p.symbol,v_p.start_at,v_p.end_at);
     IF (v_parsed->>'next_page_token') IS DISTINCT FROM v_receipt.token_out THEN
        RAISE EXCEPTION 'Stored continuation token differs from source page'; END IF;
     IF v_receipt.token_out IS NOT NULL THEN
       IF v_receipt.token_out=ANY(v_seen_tokens) THEN
         RAISE EXCEPTION 'Retained source repeats a pagination token'; END IF;
       v_seen_tokens:=pg_catalog.array_append(v_seen_tokens,v_receipt.token_out);
     END IF;
     -- The parser deduplicates identical bars. Preserve raw occurrence cardinality.
     IF pg_catalog.jsonb_array_length(COALESCE(
          (v_receipt.raw_body::jsonb)->'bars'->v_p.symbol,'[]'::jsonb))
        <>pg_catalog.jsonb_array_length(v_parsed->'records') THEN
       RAISE EXCEPTION 'Duplicate source bar within retained page'; END IF;
     FOR v_payload IN SELECT value FROM pg_catalog.jsonb_array_elements(v_parsed->'records')
     LOOP
       v_key:=(v_payload->>'symbol')||'|'||(v_payload->>'timestamp');
       IF v_expected ? v_key THEN RAISE EXCEPTION 'Duplicate source bar across retained pages'; END IF;
       v_expected:=v_expected || pg_catalog.jsonb_build_object(v_key,v_payload);
     END LOOP;
     v_token:=v_receipt.token_out;
     v_pages:=v_pages+1;
   END LOOP;
   IF v_pages=0 OR v_token IS NOT NULL OR v_pages<>v_p.page_count
      OR v_p.next_page_token IS NOT NULL THEN
     RAISE EXCEPTION 'Original source receipt chain is incomplete'; END IF;
   FOR v_row IN SELECT * FROM astra_ingestion_v1.records
      WHERE partition_id=v_p.id ORDER BY record_key
   LOOP
     PERFORM astra_ingestion_v1.rpc_json_unique(v_row.payload::json);
     v_payload:=v_row.payload::jsonb;
     v_key:=(v_payload->>'symbol')||'|'||(v_payload->>'timestamp');
     IF v_key IS NULL OR v_row.record_key<>v_key OR v_actual ? v_key THEN
        RAISE EXCEPTION 'Stored payload key or cardinality mismatch'; END IF;
     v_actual:=v_actual || pg_catalog.jsonb_build_object(v_key,v_payload);
   END LOOP;
   SELECT count(*) INTO v_expected_count FROM pg_catalog.jsonb_object_keys(v_expected);
   SELECT count(*) INTO v_actual_count FROM pg_catalog.jsonb_object_keys(v_actual);
   IF v_expected_count=0 OR v_expected_count<>v_actual_count
      OR v_expected_count<>v_p.record_count OR v_expected<>v_actual THEN
     RAISE EXCEPTION 'Source-to-target readback is not identical'; END IF;
 EXCEPTION WHEN OTHERS THEN
   -- Do not disclose raw licensed responses or SQL exceptions in persistent data.
   v_state:='failed'; v_failure:=SQLSTATE;
 END;
 -- Hashes are computed from retained in-transaction readback data only.
 v_expected_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
   astra_ingestion_v1.rpc_canonical(v_expected),'UTF8')),'hex');
 v_actual_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
   astra_ingestion_v1.rpc_canonical(v_actual),'UTF8')),'hex');
 INSERT INTO astra_ingestion_v1.independent_verifications(
   partition_id,verifier_version,job_id,scope_hash,result,failure_code,
   receipt_count,source_count,stored_count,expected_sha256,stored_sha256)
 VALUES(v_p.id,'sql_v1',v_j.id,v_j.scope_hash,v_state,v_failure,
        v_pages,v_expected_count,v_actual_count,v_expected_hash,v_actual_hash);
 RETURN pg_catalog.jsonb_build_object('state','attested','partition_id',v_p.id,
            'result',v_state,'source_count',v_expected_count,
            'stored_count',v_actual_count,'receipt_count',v_pages,
            'coverage_certification','NOT_CERTIFIED');
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.monitor_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
 SET lock_timeout TO '2s'
AS $function$
DECLARE
  v_now double precision := EXTRACT(EPOCH FROM pg_catalog.clock_timestamp());
  v_not_before double precision := 0;
  v_job astra_ingestion_v1.jobs%ROWTYPE;
  v_part record;
  v_reason text;
  v_new integer := 0;
  v_added integer := 0;
  v_active integer := 0;
  v_seen integer := 0;
BEGIN
  IF NOT pg_catalog.pg_try_advisory_xact_lock(706314020261029) THEN
    RETURN pg_catalog.jsonb_build_object('state','already_running');
  END IF;

  -- backfill_delivery_monitor_hook_v2: bounded immutable readback and finalization.
  PERFORM astra_ingestion_v1.backfill_maintain_v2(2);
  SELECT COALESCE(next_request_at,0) INTO v_not_before
    FROM astra_ingestion_v1.source_limits WHERE id='alpaca';
  v_not_before := COALESCE(v_not_before,0);
  SELECT COUNT(*) INTO v_active FROM astra_ingestion_v1.jobs
    WHERE status IN ('queued','running');

  -- Expired deadlines are a genuine useful-progress failure even if all
  -- workers are offline. Do not mutate an admitted job or extend its deadline.
  FOR v_job IN SELECT * FROM astra_ingestion_v1.jobs
     WHERE status IN ('queued','running') AND deadline_at <= v_now-60
  LOOP
    INSERT INTO astra_ingestion_v1.monitor_incidents
      (job_id,partition_id,generation,reason,observed_job_status,
       observed_deadline_at,observed_progress_at,observed_job_requests,observed_job_records)
    VALUES (v_job.id,'',0,'deadline_overdue',v_job.status,
            v_job.deadline_at,v_job.last_progress_at,v_job.request_count,v_job.record_count)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_added = ROW_COUNT;
    v_new := v_new+v_added;
  END LOOP;

  FOR v_part IN
    SELECT p.id,p.job_id,p.status,p.generation,p.lease_until,p.next_attempt_at,
           p.last_progress_at,p.page_count,
           j.status AS job_status,j.deadline_at,j.created_at,
           j.last_progress_at AS job_progress_at,j.request_count,j.record_count,
           (SELECT COUNT(*) FROM astra_ingestion_v1.partitions q
             WHERE q.job_id=p.job_id
               AND q.status IN ('running','verifying')
               AND q.lease_until>v_now) AS live_claims
      FROM astra_ingestion_v1.partitions p
      JOIN astra_ingestion_v1.jobs j ON j.id=p.job_id
     WHERE j.status IN ('queued','running') AND j.deadline_at>v_now
  LOOP
    v_seen := v_seen+1;
    v_reason := NULL;
    IF v_part.status IN ('running','verifying')
       AND v_part.lease_until IS NOT NULL
       AND v_part.lease_until<=v_now-60 THEN
       v_reason := 'lease_expired';
    ELSIF v_part.status IN ('pending','loaded')
       AND v_part.live_claims=0
       AND v_part.next_attempt_at<=v_now-240
       AND COALESCE(v_part.last_progress_at,v_part.created_at)<=v_now-240
       AND COALESCE(v_part.job_progress_at,v_part.created_at)<=v_now-240
       AND (v_part.status='loaded' OR v_not_before<=v_now) THEN
       v_reason := 'eligible_unclaimed';
    END IF;
    IF v_reason IS NOT NULL THEN
      INSERT INTO astra_ingestion_v1.monitor_incidents
        (job_id,partition_id,generation,reason,observed_job_status,
         observed_partition_status,observed_progress_at,observed_deadline_at,
         observed_job_requests,observed_job_records,observed_partition_pages)
      VALUES (v_part.job_id,v_part.id,v_part.generation,v_reason,
              v_part.job_status,v_part.status,v_part.last_progress_at,v_part.deadline_at,
              v_part.request_count,v_part.record_count,v_part.page_count)
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_added = ROW_COUNT;
      v_new := v_new+v_added;
    END IF;
  END LOOP;
  INSERT INTO astra_ingestion_v1.monitor_ticks(active_jobs,new_incidents,observed_partitions)
  VALUES (v_active,v_new,v_seen);
  RETURN pg_catalog.jsonb_build_object('state','observed','active_jobs',v_active,
           'observed_partitions',v_seen,'new_incidents',v_new,
           'disposition','FAIL_CLOSED_MANUAL_REVIEW');
END
$function$
